#!/usr/bin/env node
/**
 * Put the taxonomy vocabulary into the app, as text.
 *
 * ```
 * content/taxonomy.json
 *          ↓
 * apps/mobile/src/taxonomy/generated/vocabulary.ts   ← committed, --check in gate 11
 * ```
 *
 * The same shape as `generate-rules-bundle.mjs` and `generate-corpus-bundle.mjs`, with **one
 * deliberate step down**: there is no digest and no ledger row.
 *
 * That is a judgement about what the chain is for, not an oversight. A corrupted corpus bundle
 * shows a wrong **colour claim**; a corrupted vocabulary shows wrong **words**. The digest chain
 * exists for the first. Here the content gate validates the source — including completeness in
 * both directions against the authored corpus — `--check` proves the shipped copy matches it,
 * and the diff is what a reviewer reads. That is the same control the source register itself
 * has, and the register is what decides whether a colour may ship at all.
 *
 * `--check` is not optional: a generator whose output is never compared is a generator nobody
 * is checking [[generating-an-artefact-is-not-checking-it]], and F-094 was the whole cost of
 * learning that the second time.
 *
 * ```
 * node scripts/generate-taxonomy-bundle.mjs           regenerate
 * node scripts/generate-taxonomy-bundle.mjs --check   verify it is current, write nothing
 * ```
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCorpusPackage, ROOT } from './corpus-io.mjs';

const GREEN = '\x1b[32m',
  RED = '\x1b[31m',
  DIM = '\x1b[2m',
  BOLD = '\x1b[1m',
  OFF = '\x1b[0m';

const CHECK = process.argv.includes('--check');

const SOURCE = join(ROOT, 'content', 'taxonomy.json');
const OUT_DIR = join(ROOT, 'apps', 'mobile', 'src', 'taxonomy', 'generated');
const OUT = join(OUT_DIR, 'vocabulary.ts');

const { parseTaxonomyVocabulary } = await loadCorpusPackage();

if (!existsSync(SOURCE)) {
  console.log(`\n${RED}${BOLD}No taxonomy vocabulary.${OFF} ${SOURCE} is missing.\n`);
  process.exit(1);
}

const text = readFileSync(SOURCE, 'utf8');

// Parsed before it is bundled, and by the SAME function the gate uses — a file the app could
// not load has no business being handed to it to try.
const vocabulary = parseTaxonomyVocabulary(JSON.parse(text), 'taxonomy.json');

const generated = `/* eslint-disable */
// prettier-ignore
/**
 * GENERATED by \`node scripts/generate-taxonomy-bundle.mjs\`. Do not edit.
 *
 * The family vocabulary as text. Verified current by \`--check\` inside \`gate:content\`, so
 * editing content/taxonomy.json without regenerating fails the build rather than shipping the
 * old words.
 *
 * No digest: a corrupted vocabulary shows wrong WORDS, not a wrong colour claim, and the
 * content gate validates the source in both directions. See the generator for the argument.
 */

/** Families in the vocabulary. Here so a load can be checked against what was published. */
export const VOCABULARY_FAMILY_COUNT = ${String(vocabulary.families.length)};

export const VOCABULARY_TEXT = ${JSON.stringify(text)};
`;

if (CHECK) {
  const current = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  if (current !== generated) {
    console.log(
      `\n${RED}${BOLD}The generated vocabulary module is stale.${OFF}\n` +
        `${DIM}  ${OUT}\n  Run \`node scripts/generate-taxonomy-bundle.mjs\`.${OFF}\n`,
    );
    process.exit(1);
  }
  console.log(
    `${GREEN}${BOLD}Taxonomy bundle current.${OFF} ` +
      `${DIM}${String(vocabulary.families.length)} famil(ies).${OFF}`,
  );
  process.exit(0);
}

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, generated, 'utf8');
console.log(
  `${GREEN}${BOLD}Taxonomy bundle written.${OFF} ` +
    `${DIM}${String(vocabulary.families.length)} famil(ies), ${String(text.length)} bytes.${OFF}`,
);
